var i=`0907-sweet-and-sour-pork`;var n=`world-0907`;var a=`CN`;var r=`east-asia`;var s=4;var o=63;var d={en:`Sweet and Sour Pork`,ua:`Свинина в кисло-солодкому соусі`};var l={en:`Sweet and Sour Pork is a China dish made with pork shoulder, light soy sauce, cornstarch, chicken egg. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Свинина в кисло-солодкому соусі, страва кухні країни Китай. Основні складники: свиняча лопатка, світлий соєвий соус, кукурудзяний крохмаль, куряче яйце. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 20 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 20 хвилин.`,t:[`marinating`],m:20,i:[[`pork-shoulder`,650,`g`],[`light-soy-sauce`,30,`ml`],[`shaoxing-wine`,30,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:8,i:[[`cornstarch`,130,`g`],[`chicken-egg`,1,`pcs`]]},{en:`Fry the coated pork in batches until crisp and fully cooked; drain before tossing with the sauce.`,ua:`Смажте паніровану свинину партіями до хрусткості й повної готовності, обсушіть перед змішуванням із соусом.`,t:[`deep-frying`],m:16,i:[[`peanut-oil`,700,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`red-bell-pepper`,200,`g`],[`pineapple`,240,`g`],[`yellow-onion`,140,`g`]]},{en:`Simmer the liquid and flavorings uncovered for about 8 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 8 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:8,i:[[`rice-vinegar`,70,`ml`],[`ketchup`,100,`g`],[`white-granulated-sugar`,65,`g`],[`water`,100,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:3,i:[]}];var g={slug:i,id:n,country:`CN`,region:r,servings:4,minutes:63,title:d,text:l,steps:u};export{a as country,g as default,n as id,o as minutes,r as region,s as servings,i as slug,u as steps,l as text,d as title};